export const templatesFor = (required: ReserveClass): readonly PerturbedTemplate[] => PERTURBED_TEMPLATES.filter(template => template.required === required);
export const templateById = (id: string): PerturbedTemplate | undefined => PERTURBED_TEMPLATES.find(template => template.id === id);
export function columnsForTemplate(template: PerturbedTemplate): Tile[][] {
  const counts = Array<number>(9).fill(0);
  const columns = template.columns.map(column => [...column].map(value => {
    const kind = Number(value) as TileKind;
    if (!Number.isInteger(kind) || kind < 0 || kind > 8) throw new Error('Invalid template kind');
    return { id: kind * 12 + counts[kind]!++, kind, open: false };
  }));
  if (counts.some(count => count !== 12)) throw new Error('Invalid template inventory');
  return columns;
}
export function solutionForTemplate(template: PerturbedTemplate): ProofAction[] {
  const location = (index: number): {zone:'column'|'reserve';index:number} => index < 10 ? {zone:'column',index} : {zone:'reserve',index:index-10};
  return template.solution.map(action => action[0] === 'r' ? {type:'reveal',column:action[1],index:0} : {type:'move',from:location(action[1]),to:location(action[2]),count:action[3]});
}
